args.command:
probe(){ # x y zstart zmin
 for z in $(seq $3 -2 $4); do arm move $1 $2 $z >/dev/null; r=$(ft read 100); if echo "$r" | grep -qE 'Fz=\+[0-9]+\.[0-9]+' && [ $(echo "$r" | sed -E 's/.*Fz=\+?(-?[0-9.]+).*/\1/' | awk '{print ($1>0.5)}') = 1 ]; then echo "contact at $1 $2 z=$z: $r"; arm move $1 $2 $(( z+6 )) >/dev/null; return; fi; done; echo "no contact down to $4"; }
probe 500 30 120 40

tool_calls.raw:
{"command": "cd ~; python3 - <<'EOF'
import workcell
def mv(x,y,z):
    workcell.call("arm","move",str(x),str(y),str(z)); s=workcell.call("arm","status","--json").data["tip_mm"]
    ok=max(abs(s[0]-x),abs(s[1]-y),abs(s[2]-z))<1
    if not ok: print("DEVIATION", (x,y,z), s)
    return ok
if mv(415,0,140) and mv(415,0,60) and mv(415,0,30):
    print(workcell.call("ft","read","200","--json").data)
    for x in [420,422,423,423.5,424,424.5,425,425.5,426]:
        workcell.call("arm","move",str(x),"0","30"); s=workcell.call("arm","status","--json").data; f=workcell.call("ft","read","300","--json").data
        print("cmd x %.1f enc %s  Fx=%.2f Fy=%.2f Fz=%.2f"%(x,s["tip_mm"],f["fx"],f["fy"],f["fz"]))
        if abs(f["fx"])>40 or abs(f["fz"])>40: break
    mv(415,0,30); mv(415,0,140)
EOF"}

